import { Component, OnInit, OnDestroy, ElementRef, ViewChild, ChangeDetectorRef } from '@angular/core';
import { forkJoin } from 'rxjs';
import { DashboardService } from '../services/dashboard.service';
import { AuthService } from '../services/auth.service';

declare const Chart: any;

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.html',
  styleUrls: ['./dashboard.css']
})
export class DashboardComponent implements OnInit, OnDestroy {

  @ViewChild('lineChart') lineChartRef!: ElementRef<HTMLCanvasElement>;
  @ViewChild('pieChart')  pieChartRef!: ElementRef<HTMLCanvasElement>;

  today = new Date();
  loading = true;
  error = '';

  summary: any = { tasksCompleted: 0, tasksPending: 0, timeSpent: 0, productivityScore: 0 };
  insights: string[] = [];
  recommendations: string[] = [];
  heatmapCells: { level: number; date: string }[] = [];

  private lineChart: any;
  private pieChart: any;
  private userId = '';
  private trendData: any[] = [];
  private catData: any[] = [];

  get score() { return this.summary.productivityScore ?? 0; }
  circumference = 2 * Math.PI * 36;
  get dashOffset() { return this.circumference * (1 - this.score / 100); }

  get stats() {
    return [
      { icon: '✅', label: 'Tasks Completed Today', value: this.summary.tasksCompleted, color: '#10b981' },
      { icon: '⏳', label: 'Tasks Pending',          value: this.summary.tasksPending,   color: '#f59e0b' },
      { icon: '🕐', label: 'Time Spent Today (min)', value: this.summary.timeSpent,      color: '#6366f1' },
    ];
  }

  constructor(
    private dash: DashboardService,
    private auth: AuthService,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnInit() {
    const user = this.auth.getUser();
    if (!user?.id) {
      this.error = 'Not authenticated';
      this.loading = false;
      return;
    }
    this.userId = user.id;
    this.loadAll();
  }

  ngOnDestroy() {
    this.lineChart?.destroy();
    this.pieChart?.destroy();
  }

  loadAll() {
    this.loading = true;
    this.error = '';

    forkJoin({
      summary:  this.dash.getSummary(this.userId),
      trend:    this.dash.getTaskTrend(this.userId),
      category: this.dash.getCategoryDistribution(this.userId),
      heatmap:  this.dash.getHeatmap(this.userId),
      insights: this.dash.getInsights(this.userId)
    }).subscribe({
      next: (res: any) => {
        this.summary         = res.summary;
        this.trendData       = res.trend;
        this.catData         = res.category;
        this.insights        = res.insights.insights;
        this.recommendations = res.insights.recommendations;
        this.buildHeatmap(res.heatmap);

        this.loading = false;
        this.cdr.detectChanges(); // flush *ngIf so canvases appear in DOM

        // canvases are now in DOM — render charts
        setTimeout(() => {
          this.renderLineChart(this.trendData);
          this.renderPieChart(this.catData);
        }, 0);
      },
      error: (e: any) => {
        this.error   = e?.error?.detail || 'Failed to load dashboard data. Is the backend running?';
        this.loading = false;
      }
    });
  }

  refresh() {
    this.dash.invalidate();
    this.lineChart?.destroy(); this.lineChart = null;
    this.pieChart?.destroy();  this.pieChart  = null;
    this.loadAll();
  }

  private buildHeatmap(data: { date: string; count: number }[]) {
    const map: Record<string, number> = {};
    data.forEach(d => (map[d.date] = d.count));
    const maxCount = Math.max(...data.map(d => d.count), 1);

    this.heatmapCells = [];
    const today = new Date();
    for (let i = 29; i >= 0; i--) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      const key   = d.toISOString().split('T')[0];
      const label = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      const cnt   = map[key] ?? 0;
      const level = cnt === 0 ? 0 : Math.ceil((cnt / maxCount) * 4);
      this.heatmapCells.push({ level, date: `${label} — ${cnt} tasks` });
    }
  }

  private renderLineChart(data: { date: string; count: number }[]) {
    if (!this.lineChartRef?.nativeElement) return;
    this.lineChart?.destroy();
    this.lineChart = new Chart(this.lineChartRef.nativeElement, {
      type: 'line',
      data: {
        labels: data.map(d => d.date.slice(5)),
        datasets: [{
          label: 'Tasks Created',
          data: data.map(d => d.count),
          borderColor: '#f59e0b',
          backgroundColor: 'rgba(245,158,11,0.08)',
          pointBackgroundColor: '#f59e0b',
          pointRadius: 5, pointHoverRadius: 7,
          tension: 0.4, fill: true, borderWidth: 2.5
        }]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        animation: { duration: 900, easing: 'easeInOutQuart' },
        plugins: { legend: { display: false } },
        scales: {
          x: { grid: { color: '#1f1f1f' }, ticks: { color: '#6b7280', font: { family: 'Inter', size: 12 } } },
          y: { grid: { color: '#1f1f1f' }, ticks: { color: '#6b7280', font: { family: 'Inter', size: 12 }, stepSize: 1 }, beginAtZero: true }
        }
      }
    });
  }

  private renderPieChart(data: { category: string; count: number }[]) {
    if (!this.pieChartRef?.nativeElement) return;
    this.pieChart?.destroy();
    const colors = ['#f59e0b', '#6366f1', '#10b981', '#ec4899', '#3b82f6', '#ef4444'];
    this.pieChart = new Chart(this.pieChartRef.nativeElement, {
      type: 'doughnut',
      data: {
        labels: data.map(d => d.category),
        datasets: [{
          data: data.map(d => d.count),
          backgroundColor: colors.slice(0, data.length),
          borderColor: '#111111', borderWidth: 3, hoverOffset: 8
        }]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        animation: { duration: 900, easing: 'easeInOutQuart' },
        plugins: {
          legend: {
            position: 'bottom',
            labels: { color: '#9ca3af', font: { family: 'Inter', size: 12 }, padding: 16, boxWidth: 12 }
          }
        },
        cutout: '65%'
      }
    });
  }
}
